  "parameter.web_search.max_results": "Maximum results. Default: 8; range: 1-20.",
  "parameter.fetch_url.url": "Public HTTP or HTTPS URL for a new fetch. Omit when source_id is supplied.",
  "parameter.fetch_url.source_id": "Saved response ID from fetch_url. Use instead of url to continue that response.",
  "parameter.fetch_url.offset": "Offset returned by next_offset. Default: 0; do not calculate it yourself.",
  "parameter.ssh_connect.destination": "user@host. Not with target_id.",
  "parameter.ssh_connect.port": "SSH port. Default: 22.",
  "parameter.ssh_connect.identity_file": "Path of a private key file on this computer (not its contents). Default: ssh's default keys and agent.",
  "parameter.ssh_connect.name": "Name the app shows for the host. Default: destination.",
