export type PromptKey = keyof typeof PROMPT_TEXT

/** The text under `key` with its placeholders filled; a placeholder without a value is an error, not a blank. */
export function text(key: PromptKey, vars: Record<string, string | number> = {}): string {
  return PROMPT_TEXT[key].replace(/\{([a-z_]+)\}/g, (_m, name: string) => {
    if (!(name in vars)) throw new Error(`prompt text ${key}: no value for {${name}}`)
    return String(vars[name])
  })
}

/** The placeholders a text carries, in order of first appearance. */
export function placeholdersOf(key: PromptKey): string[] {
  const out: string[] = []
  for (const m of PROMPT_TEXT[key].matchAll(/\{([a-z_]+)\}/g)) if (!out.includes(m[1]!)) out.push(m[1]!)
  return out
}
